// Scalar native stages: ATLAS (interval compiler), PACK (image builder +
// real-image lookup), TRACE (lookup over supplied image bytes) and the internal
// PLAN stage used by the JSON compiler.  One translation unit, C++17,
// baseline x86-64 only.
#include "engine.hpp"
#include "plan.hpp"
#include <iostream>
#include <string>
#include <vector>

static void stage_atlas() {
    size_t n;
    if (!(std::cin >> n)) throw std::runtime_error("atlas count");
    std::vector<Entry> fib;
    fib.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        std::string s; long long length, hop;
        if (!(std::cin >> s >> length >> hop)) throw std::runtime_error("atlas row");
        fib.push_back(make_entry(s, (int)length, hop));
    }
    std::vector<Run> runs = atlas_runs(fib);
    std::cout << runs.size() << '\n';
    for (size_t i = 0; i < runs.size(); ++i)
        std::cout << hexkey(runs[i].start) << ' ' << runs[i].hop << '\n';
}

static void stage_pack() {
    size_t r, n, a;
    if (!(std::cin >> r >> n >> a)) throw std::runtime_error("pack header");
    std::vector<Key> starts;
    std::vector<long long> hops;
    for (size_t i = 0; i < r; ++i) {
        std::string s; long long hop;
        if (!(std::cin >> s >> hop)) throw std::runtime_error("pack run");
        starts.push_back(key(s)); hops.push_back(hop);
    }
    std::vector<Layout> nodes;
    for (size_t i = 0; i < n; ++i) {
        Layout node; size_t b;
        if (!(std::cin >> node.lo >> node.span >> node.mode >> node.cached >> b))
            throw std::runtime_error("pack node");
        for (size_t j = 0; j < b; ++j) { int c; if (!(std::cin >> c)) throw std::runtime_error("pack child"); node.children.push_back(c); }
        nodes.push_back(node);
    }
    std::vector<Key> addresses;
    for (size_t i = 0; i < a; ++i) { std::string s; if (!(std::cin >> s)) throw std::runtime_error("pack address"); addresses.push_back(key(s)); }
    PackedResult res = pack_image(starts, hops, nodes, addresses);
    std::cout << res.image << '\n';
    for (size_t i = 0; i < res.answers.size(); ++i) {
        const Answer& ans = res.answers[i];
        std::cout << ans.hop << ' ' << ans.run << ' ' << ans.path.size();
        for (size_t k = 0; k < ans.path.size(); ++k) std::cout << ' ' << ans.path[k];
        std::cout << '\n';
    }
}

static void stage_trace() {
    size_t n;
    std::string image;
    if (!(std::cin >> n >> image)) throw std::runtime_error("trace header");
    std::vector<Key> addresses;
    for (size_t i = 0; i < n; ++i) { std::string s; if (!(std::cin >> s)) throw std::runtime_error("trace address"); addresses.push_back(key(s)); }
    std::vector<Answer> res = trace_image(image, addresses);
    for (size_t i = 0; i < res.size(); ++i) {
        std::cout << res[i].hop << ' ' << res[i].run << ' ' << res[i].path.size();
        for (size_t k = 0; k < res[i].path.size(); ++k) std::cout << ' ' << res[i].path[k];
        std::cout << '\n';
    }
}

// PLAN <versions> <cache_pages> <hit> <miss> <d0> <d1> <d2>
//   per version: R / R rows "start hop" / B / B rows "repeat m idx..."
// prints the jointly optimal layout of every version after sharing the budget.
static void stage_plan() {
    size_t versions;
    if (!(std::cin >> versions)) throw std::runtime_error("plan header");
    PlanCosts pc;
    long long hit, miss, d0, d1, d2;
    if (!(std::cin >> pc.C >> hit >> miss >> d0 >> d1 >> d2)) throw std::runtime_error("plan costs");
    if (versions == 0 || pc.C < 0 || pc.C > 12) throw std::runtime_error("plan bounds");
    pc.hit = hit; pc.miss = miss; pc.dec[0] = d0; pc.dec[1] = d1; pc.dec[2] = d2;
    int C = pc.C;
    std::vector<PlanVer> in(versions);
    std::vector<VersionPlan> vps(versions);
    for (size_t v = 0; v < versions; ++v) {
        PlanVer& pv = in[v];
        if (!(std::cin >> pv.R)) throw std::runtime_error("plan runs");
        pv.starts.clear(); pv.hops.clear();
        for (int i = 0; i < pv.R; ++i) {
            std::string s; long long hop;
            if (!(std::cin >> s >> hop)) throw std::runtime_error("plan run");
            pv.starts.push_back(key(s)); pv.hops.push_back(hop);
        }
        size_t b;
        if (!(std::cin >> b)) throw std::runtime_error("plan bursts");
        for (size_t k = 0; k < b; ++k) {
            PlanBurst burst;
            long long m;
            if (!(std::cin >> burst.repeat >> m)) throw std::runtime_error("plan burst");
            for (long long z = 0; z < m; ++z) { int idx; if (!(std::cin >> idx)) throw std::runtime_error("plan index"); burst.idx.push_back(idx); }
            pv.bursts.push_back(burst);
        }
        plan_version(pv, pc, vps[v]);
    }
    // share the resident page budget across immutable versions
    std::vector<i128> cur((size_t)C + 1, 0), nxt((size_t)C + 1);
    std::vector<std::vector<int> > pick(versions, std::vector<int>((size_t)C + 1, 0));
    for (size_t v = 0; v < versions; ++v) {
        for (int cap = 0; cap <= C; ++cap) {
            i128 best = PLAN_INF; int bc = 0;
            for (int c = 0; c <= cap; ++c) {
                i128 val = cur[cap - c] + vps[v].phi[(size_t)c];
                if (val < best) { best = val; bc = c; }
            }
            nxt[cap] = best; pick[v][cap] = bc;
        }
        cur = nxt;
    }
    std::vector<int> caps(versions, 0);
    int cap = C;
    for (size_t k = versions; k-- > 0;) { caps[k] = pick[k][cap]; cap -= caps[k]; }
    std::cout << versions << '\n';
    for (size_t v = 0; v < versions; ++v) {
        std::vector<Layout> nodes;
        plan_reconstruct(vps[v], caps[v], nodes);
        plan_check(in[v].starts, nodes);
        std::cout << nodes.size() << '\n';
        for (size_t i = 0; i < nodes.size(); ++i) {
            const Layout& n = nodes[i];
            std::cout << n.lo << ' ' << n.span << ' ' << n.mode << ' ' << n.cached
                      << ' ' << n.children.size();
            for (size_t c = 0; c < n.children.size(); ++c) std::cout << ' ' << n.children[c];
            std::cout << '\n';
        }
    }
}

int main() {
    try {
        std::string command;
        if (!(std::cin >> command)) throw std::runtime_error("native command");
        if (command == "ATLAS") stage_atlas();
        else if (command == "PACK") stage_pack();
        else if (command == "TRACE") stage_trace();
        else if (command == "PLAN") stage_plan();
        else throw std::runtime_error("unknown native command");
        if (!std::cin && !std::cin.eof()) throw std::runtime_error("truncated native input");
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
    return 0;
}
